def solve(rows):
    from collections import defaultdict

    # Filter rows with day <= 24
    filtered_rows = [row for row in rows if row['day'] <= 24]

    # Extract all days from the filtered rows
    days = set()
    for row in filtered_rows:
        days.add(row['day'])

    if not days:
        return [0, None]

    # Sort days for consecutive check
    sorted_days = sorted(days)
    n = len(sorted_days)
    max_run = 1
    current_run = 1
    for i in range(1, n):
        if sorted_days[i] == sorted_days[i - 1] + 1:
            current_run += 1
            if current_run > max_run:
                max_run = current_run
        else:
            current_run = 1

    # Find the earliest run with maximum length
    result = []
    for i in range(n):
        if sorted_days[i] == sorted_days[0] + i:
            run_length = i + 1
            if run_length > max_run:
                max_run = run_length
                result = [(run_length, sorted_days[i])]
            elif run_length == max_run:
                result.append((run_length, sorted_days[i]))

    if not result:
        return [0, None]

    # Sort by run length descending, then by day ascending
    result.sort(key=lambda x: (-x[0], x[1]))
    return result
```

