    for row in rows:
        if row['status'] == 'delivered':
            delivered_days.add(row['day'])

    if not delivered_days:
        return [0, None]

    sorted_days = sorted(delivered_days)
    max_length = 1
    current_length = 1
    first_day = sorted_days[0]

    for i in range(1, len(sorted_days)):
        if sorted_days[i] == sorted_days[i - 1] + 1:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
                first_day = sorted_days[i - current_length]
            current_length = 1

    if current_length > max_length:
        max_length = current_length
        first_day = sorted_days[-current_length]

    return [max_length, first_day]
