def solve(rows):
    if not rows:
        return [0, None]

    # Filter rows for 'east' or 'west' regions
    filtered_rows = [row for row in rows if row['region'] in ['east', 'west']]

    # Initialize balance and tracking
    balance = 0
    lowest_balance = float('inf')
    lowest_balance_day = None
    lowest_balance_order_id = None

    for row in sorted(filtered_rows, key=lambda x: (x['day'], x['order_id'])):
        if row['status'] in ['cancelled', 'delayed']:
            if row['status'] == 'cancelled':
                balance += row['quantity']
            else:
                balance -= row['quantity']

            if balance < lowest_balance:
                lowest_balance = balance
                lowest_balance_day = row['day']
                lowest_balance_order_id = row['order_id']
            elif balance == lowest_balance:
                if row['order_id'] < lowest_balance_order_id:
                    lowest_balance_order_id = row['order_id']

    if lowest_balance == float('inf'):
        return [0, None]
    else:
        return [lowest_balance, lowest_balance_day]
