            region_data[region] = {'cancelled': 0, 'total': 0}
        region_data[region]['total'] += 1
        if status == 'cancelled':
            region_data[region]['cancelled'] += 1

    # Calculate percentage and filter by percentage >= 25
    result = []
    for region, data in region_data.items():
        count = data['cancelled']
        total = data['total']
        if total == 0:
            continue
        percentage = round(100 * count / total, 1)
        if percentage >= 25:
            result.append([region, percentage])

    # Sort by percentage descending and then value ascending
    result.sort(key=lambda x: (-x[1], x[0]))

    return result
