def solve(rows):
    # Filter rows with day at most 17
    filtered_rows = [row for row in rows if row['day'] <= 17]

    # Sort by day ascending, then order_id ascending
    filtered_rows.sort(key=lambda x: (x['day'], x['order_id']))

    balance = 0
    min_balance = float('inf')
    min_day = None

    for row in filtered_rows:
        # Skip rows that are not 'delayed' or 'delivered'
        if row['status'] not in ('delayed', 'delivered'):
            continue

        # Update balance based on status
        if row['status'] == 'delayed':
            balance += row['quantity']
        elif row['status'] == 'delivered':
            balance -= row['quantity']

        # Record balance if it's the minimum
        if balance < min_balance:
            min_balance = balance
            min_day = row['day']

        # If balance is 0, break early
        if balance == 0:
            break

    if min_balance != float('inf'):
        return [min_balance, min_day]
    else:
        return [0, None]
