def solve(rows):
    from collections import defaultdict

    # Filter rows with quantity >= 3
    filtered_rows = [row for row in rows if row['quantity'] >= 3]

    # Group quantities by product
    product_quantities = defaultdict(list)
    for row in filtered_rows:
        product_quantities[row['product']].append(row['quantity'])

    # Calculate median for each product
    result = {}
    for product, quantities in product_quantities.items():
        quantities.sort()
        n = len(quantities)
        if n == 0:
            continue
        if n % 2 == 1:
            median = quantities[n // 2]
        else:
            median = (quantities[n // 2 - 1] + quantities[n // 2]) / 2
        result[product] = round(median, 1)

    return result
