def solve(rows):
    filtered_rows = [row for row in rows if row['quantity'] >= 3]
    if not filtered_rows:
        return [0, None]
    days = sorted(set(row['day'] for row in filtered_rows))
    max_length = 0
    current_length = 1
    first_day = days[0]
    for i in range(1, len(days)):
        if days[i] == days[i - 1] + 1:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
                first_day = days[i - current_length]
            current_length = 1
    if current_length > max_length:
        max_length = current_length
        first_day = days[-current_length]
    return [max_length, first_day]
