def solve(rows):
    from collections import defaultdict

    # Group rows by region
    region_groups = defaultdict(list)
    for row in rows:
        if row['status'] != 'delayed':
            region_groups[row['region']].append(row)

    # Calculate count and size for each region
    region_stats = {}
    for region, group in region_groups.items():
        count = len(group)
        if count > 0:
            region_stats[region] = (count, len(group))

    # Compute percentage for each region
    region_percentages = {}
    for region, (count, size) in region_stats.items():
        if size == 0:
            continue
        percentage = round(100 * count / size, 1)
        region_percentages[region] = percentage

    # Filter regions with percentage >= 30
    filtered_regions = [region for region, percentage in region_percentages.items() if percentage >= 30]

    # Sort by percentage descending and then value ascending
    sorted_regions = sorted(filtered_regions, key=lambda x: (-region_percentages[x], x))

    # Prepare result
    result = []
    for region in sorted_regions:
        value = region_stats[region][0]
        percentage = region_percentages[region]
        result.append((value, percentage))

    return result
```

